c.python:
class Solution:
    def earliestTime(self, tasks: List[List[int]]) -> int:
        return min(s + t for s, t in tasks)

c.cpp:
class Solution {
public:
    int earliestTime(vector<vector<int>>& tasks) {
        int best = INT_MAX;
        for (auto& t : tasks) best = min(best, t[0] + t[1]);
        return best;
    }
};

c.java:
class Solution {
    public int earliestTime(int[][] tasks) {
        int best = Integer.MAX_VALUE;
        for (int[] t : tasks) best = Math.min(best, t[0] + t[1]);
        return best;
    }
}

